// === Parsear MIME crudo (Gmail format=raw): Subject + text/html + imagenes inline por Content-ID ===
const rawB64 = $input.first().json.raw || '';
const rfc822 = Buffer.from(String(rawB64).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('binary');

function splitHeaderBody(block) {
  let idx = block.indexOf('\r\n\r\n'); let sl = 4;
  if (idx < 0) { idx = block.indexOf('\n\n'); sl = 2; }
  if (idx < 0) return { head: block, body: '' };
  return { head: block.slice(0, idx), body: block.slice(idx + sl) };
}
function parseHeaders(headText) {
  const unfolded = headText.replace(/\r?\n[ \t]+/g, ' ');
  const headers = {};
  for (const line of unfolded.split(/\r?\n/)) {
    const i = line.indexOf(':');
    if (i < 0) continue;
    headers[line.slice(0, i).trim().toLowerCase()] = line.slice(i + 1).trim();
  }
  return headers;
}
function getBoundary(ct) { const m = /boundary="?([^";]+)"?/i.exec(ct || ''); return m ? m[1] : null; }
function decodeQP(s) { return s.replace(/=\r?\n/g, '').replace(/=([0-9A-Fa-f]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16))); }
function partBuffer(part) {
  const cte = (part.headers['content-transfer-encoding'] || '7bit').toLowerCase();
  if (cte === 'base64') return Buffer.from(part.body.replace(/[^A-Za-z0-9+/=]/g, ''), 'base64');
  if (cte === 'quoted-printable') return Buffer.from(decodeQP(part.body), 'binary');
  return Buffer.from(part.body, 'binary');
}
function charsetOf(ct) { const m = /charset="?([^";]+)"?/i.exec(ct || ''); return m ? m[1].toLowerCase() : 'utf-8'; }
function toText(buf, cs) { if (/(iso-8859-1|latin1|windows-1252)/i.test(cs)) return buf.toString('latin1'); return buf.toString('utf8'); }
function decodeRfc2047(s) {
  if (!s || s.indexOf('=?') < 0) return s;
  return s.replace(/=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g, (full, cs, enc, data) => {
    try {
      let buf;
      if (enc.toUpperCase() === 'B') buf = Buffer.from(data, 'base64');
      else buf = Buffer.from(decodeQP(data.replace(/_/g, ' ')), 'binary');
      return /utf-?8/i.test(cs) ? buf.toString('utf8') : buf.toString('latin1');
    } catch (e) { return full; }
  });
}

const parts = [];
(function walk(block) {
  const sb = splitHeaderBody(block);
  const headers = parseHeaders(sb.head);
  const ct = headers['content-type'] || 'text/plain';
  if (/^multipart\//i.test(ct)) {
    const b = getBoundary(ct);
    if (!b) return;
    const segs = sb.body.split('--' + b);
    for (let i = 1; i < segs.length; i++) {
      let seg = segs[i];
      if (seg.startsWith('--')) break;
      seg = seg.replace(/^\r?\n/, '');
      walk(seg);
    }
  } else {
    parts.push({ headers, body: sb.body });
  }
})(rfc822);

const topHeaders = parseHeaders(splitHeaderBody(rfc822).head);
const subject = decodeRfc2047(topHeaders['subject'] || '');

let html = '', plain = '';
const images = [];
for (const p of parts) {
  const ct = p.headers['content-type'] || '';
  const mime = ct.split(';')[0].trim().toLowerCase();
  if (mime === 'text/html' && !html) html = toText(partBuffer(p), charsetOf(ct));
  else if (mime === 'text/plain' && !plain) plain = toText(partBuffer(p), charsetOf(ct));
  else if (mime.indexOf('image/') === 0) {
    const cid = (p.headers['content-id'] || '').replace(/^<|>$/g, '').trim();
    images.push({ cid, mime, b64: partBuffer(p).toString('base64') });
  }
}

const hasHtml = !!(html && html.trim());
if (!hasHtml) {
  const esc = String(plain || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  html = '<pre style="white-space:pre-wrap;font-family:inherit">' + esc + '</pre>';
}

const RE = /\b\d{8}\b/;
let orderNumber = null;
const mS = String(subject).match(RE);
if (mS) orderNumber = mS[0];
if (!orderNumber) {
  const bt = (plain || '') + ' ' + String(html).replace(/<[^>]+>/g, ' ');
  const mB = bt.match(RE);
  if (mB) orderNumber = mB[0];
}
const found = !!orderNumber;
const ts = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
const fileName = (found ? orderNumber : 'SIN_PEDIDO_' + ts) + '.pdf';

function escRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
const used = new Set();
for (const img of images) {
  if (!img.cid) continue;
  const uri = 'data:' + img.mime + ';base64,' + img.b64;
  const re = new RegExp('cid:' + escRe(img.cid) + '[^"\'\\s>)]*', 'gi');
  const before = html;
  html = html.replace(re, uri);
  if (html !== before) used.add(img);
}
const appended = images.filter(i => !used.has(i));
if (appended.length) {
  let extra = '<hr><p><strong>Imagenes del correo:</strong></p>';
  for (const img of appended) extra += '<div style="margin:8px 0;text-align:center"><img src="data:' + img.mime + ';base64,' + img.b64 + '" style="max-width:100%"/></div>';
  html += extra;
}

// --- Clasificacion del tipo de pedido (chapa/cristal/mixto) por palabras clave ---
const _clsSrc = (String(subject) + ' ' + (plain && plain.trim() ? plain : String(html).replace(/<[^>]+>/g, ' '))).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const _chapaRe = [/\bchapa/, /\bpleg/, /\bral\b/, /\bespesor/];
const _cristalRe = [/\bcristal/, /\bvidrio/, /3\+3/, /4\+4/, /canto pulido/, /\btemplad/, /\bmate\b/, /\btransparent/, /\bluna\b/];
const _hasChapa = _chapaRe.some(r => r.test(_clsSrc));
const _hasCristal = _cristalRe.some(r => r.test(_clsSrc));
let tipoPedido = 'Revisar';
if (_hasChapa && _hasCristal) tipoPedido = 'Mixto';
else if (_hasChapa) tipoPedido = 'Chapa';
else if (_hasCristal) tipoPedido = 'Cristal';

// --- Cabecera: Pedido + fecha/hora del email (header Date), zona Europe/Madrid ---
let emailDate = new Date(topHeaders['date'] || '');
if (isNaN(emailDate.getTime())) emailDate = new Date();
const fechaES = new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric' }).format(emailDate);
const horaES = new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false }).format(emailDate);
const fromRaw = decodeRfc2047(topHeaders['from'] || '');
const mFrom = fromRaw.match(/<([^>]+)>/);
const fromEmail = (mFrom ? mFrom[1] : fromRaw).trim();
const logoUri = "data:image/png;base64,BASE64_OMITIDO";
const pedidoLabel = found ? orderNumber : 'SIN PEDIDO';
const headerHtml = '<div style="border-bottom:2px solid #333;padding-bottom:12px;margin-bottom:18px">' +
  '<div style="text-align:left;margin-bottom:10px"><img src="' + logoUri + '" alt="Logo" style="height:72px;width:auto;display:inline-block;margin:0"/></div>' +
  '<div style="font-size:18pt;font-weight:bold;color:#111;margin-bottom:6px">Pedido: ' + pedidoLabel + '</div>' +
  '<div style="font-size:11pt;color:#555;margin-bottom:2px">Fecha: ' + fechaES + ' &nbsp;|&nbsp; Hora: ' + horaES + '</div>' +
  '<div style="font-size:11pt;color:#555;margin-bottom:2px">Enviado por: ' + fromEmail + '</div>' +
  '<div style="font-size:11pt;color:#555">Tipo: ' + tipoPedido + '</div>' +
  '</div>';
const fullHtml = '<!DOCTYPE html><html><head><meta charset="utf-8">' +
  '<style>body{font-family:Arial,Helvetica,sans-serif;font-size:12pt;color:#000;margin:24px}img{max-width:100%;height:auto;display:block;margin-left:auto;margin-right:auto}</style>' +
  '</head><body>' + headerHtml + html + '</body></html>';
const dateFolder = new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date()).replace(/\//g, '-');

let bodyText = (plain && plain.trim()) ? plain : String(html).replace(/<[^>]+>/g, ' ');
bodyText = bodyText.replace(/\r/g, '').replace(/\[image:[^\]]*\]/gi, '').replace(/\[cid:[^\]]*\]/gi, '').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
if (bodyText.length > 3000) bodyText = bodyText.slice(0, 3000) + '…';
const imagenesHtml = images.map(im => '<img src="data:' + im.mime + ';base64,' + im.b64 + '">').join(''); return [{ json: { imagenesHtml, orderNumber, found, fileName, dateFolder, fecha: fechaES, hora: horaES, fromEmail, bodyText, tipoPedido, subject, htmlString: fullHtml, imagesTotal: images.length, imagesEmbedded: used.size } }];

const s = $('Extraer pedido + preparar HTML').item.json;
function esc(t){ return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
