<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ficha de pedido</title>
<style>

@font-face{font-family:'BarlowCond';font-style:normal;font-weight:900;src:url(data:font/woff2;base64,BASE64_OMITIDO) format('woff2');}
@font-face{font-family:'BarlowCond';font-style:normal;font-weight:700;src:url(data:font/woff2;base64,BASE64_OMITIDO) format('woff2');}
@font-face{font-family:'Inter';font-style:normal;font-weight:400;src:url(data:font/woff2;base64,BASE64_OMITIDO) format('woff2');}
@font-face{font-family:'Inter';font-style:normal;font-weight:600;src:url(data:font/woff2;base64,BASE64_OMITIDO) format('woff2');}
@font-face{font-family:'Inter';font-style:normal;font-weight:700;src:url(data:font/woff2;base64,BASE64_OMITIDO) format('woff2');}
* { box-sizing:border-box; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
@page { size:A4; margin:15mm; }
html,body { margin:0; padding:0; }
body { font-family:'Inter',Arial,Helvetica,sans-serif; color:#000; background:#fff; }

/* una sola pagina: columna fija de 267mm (A4 - 2*15mm) */
.sheet { min-height:267mm; }

.ey { font-family:'Inter'; font-weight:600; letter-spacing:.14em; text-transform:uppercase; }
.sq::before { content:"\25A0"; font-size:.7em; margin-right:5px; vertical-align:1px; }

/* ---- cabecera (compacta) ---- */
.top-accent { border-top:2pt solid #000; }
.head { display:flex; align-items:flex-end; justify-content:space-between; padding:5px 0 6px; }
.brand { display:flex; align-items:center; }
.logo-svg { height:8mm; width:auto; display:block; }
.logo-svg path,.logo-svg g{ fill:#000; }
.brand-sub { font-weight:600; font-size:6.5pt; letter-spacing:.12em; text-transform:uppercase;
             margin-left:9px; padding-left:9px; border-left:.75pt solid #000; line-height:1.25; }
.doctitle { text-align:right; }
.doctitle h1 { font-family:'BarlowCond'; font-weight:700; font-size:19pt; letter-spacing:.02em;
               text-transform:uppercase; margin:0; line-height:1; }
.doctitle .mini { font-weight:400; font-size:6.5pt; letter-spacing:.08em; text-transform:uppercase; margin-top:2px; }

/* ---- hero: nº pedido + tipo ---- */
.hero { display:flex; align-items:stretch; gap:8mm; margin-top:5px; }
.hero-ped { flex:1 1 auto; }
.hero-ped .lab { font-weight:700; letter-spacing:.16em; font-size:8pt; text-transform:uppercase; }
