.meta { margin-top:6px; border-top:.5pt solid #000; border-bottom:.5pt solid #000; }
.meta table { width:100%; border-collapse:collapse; }
.meta td { padding:3px 7px; vertical-align:top; border-right:.5pt solid #000; }
