.planos { margin-top:8px; }
.planos .blk-h { break-after:avoid; page-break-after:avoid; }
.planos-grid { margin-top:5px; }
/* cada <img> inyectada (un plano): lo mas grande posible SIN recortar y sin partirse
   entre paginas. max-width 100% + max-height ~1 pagina A4 => legible con 1 o con N. */
.planos-grid img {
  display:block; margin:0 auto 4mm;
  max-width:100%; max-height:165mm;
  width:auto; height:auto;
  border:.5pt solid #000; background:#fff; padding:1.5mm;
  break-inside:avoid; page-break-inside:avoid;
}

</style></head>
<body>
<!--
==================================================================================
 FICHA DE PEDIDO (A4, UNA sola pagina) para PDF via Gotenberg/Chromium.
 Impresion oficina A4, MONOCROMO: #000 sobre #fff, sin color, sin rellenos negros macizos.
 Autocontenido (CSS + fuentes base64 + logo SVG inline). Sin JavaScript. Margenes 15mm.
 NO contiene etiquetas: la etiqueta es un documento aparte y aqui no aparece.

 MARCADORES (rellenar en n8n, dejar literales):
   {{LOGO}}         opcional; por defecto va el logo de la empresa (SVG). Para inyectar el tuyo,
                    sustituye el <svg class="logo-svg">...</svg> por {{LOGO}} o tu <img>.
   {{PEDIDO}}       nº de pedido (grande)
   {{TIPO}}         CHAPA / CRISTAL / MIXTO / REVISAR
   {{FECHA}} {{HORA}} {{REMITENTE}} {{ASUNTO}}
   {{CUERPO_TEXTO}} texto del cliente (se respetan saltos de linea via white-space:pre-wrap).
                    Bloque compacto/secundario; acotado a ~34mm para no comerse los planos.
   {{IMAGENES}}     una o varias <img> (los planos). SE INYECTA TAL CUAL (no escapar).
                    Se colocan en la zona de planos y se ajustan ENTERAS (object-fit:contain),
                    lo mas grandes posible, repartiendose la zona. Funciona con 1 o con N.

 Toda la pagina es una columna fija de 267mm con overflow:hidden -> SIEMPRE 1 pagina, sin blancos.
==================================================================================
-->

<div class="sheet">

  <div class="top-accent"></div>
  <div class="head">
    <div class="brand">
      <span class="brand-mark"><!-- logo de la empresa --></span>
      <span class="brand-sub">Empresa<br>Taller de chapa</span>
    </div>
    <div class="doctitle">
      <h1>Ficha de pedido</h1>
      <div class="mini">Documento generado automaticamente</div>
    </div>
  </div>
  <hr style="border:0;border-top:1pt solid #000;margin:0">

  <div class="hero">
    <div class="hero-ped">
      <div class="lab sq">Nº de pedido</div>
      <div class="num">{{PEDIDO}}</div>
    </div>
    <div class="tipo-box">
      <div class="lab">Tipo</div>
      <div class="val">{{TIPO}}</div>
    </div>
  </div>

  <div class="meta">
    <table>
      <tr><td class="k">Fecha</td><td class="v">{{FECHA}}</td>
          <td class="k">Hora</td><td class="v">{{HORA}}</td></tr>
      <tr><td class="k">Enviado por</td><td class="v" colspan="3">{{REMITENTE}}</td></tr>
      <tr><td class="k">Asunto</td><td class="v" colspan="3">{{ASUNTO}}</td></tr>
    </table>
  </div>

  <div class="cliente">
    <div class="blk-h sq">Indicaciones del cliente</div>
    <div class="cliente-txt">{{CUERPO_TEXTO}}</div>
  </div>

  <div class="planos">
    <div class="blk-h sq">Planos / piezas a fabricar</div>
    <div class="planos-grid">{{IMAGENES}}</div>
  </div>

</div>

</body></html>
";
html = html.replace(/<!--[\s\S]*?-->/g, '');
html = html.split('{{PEDIDO}}').join(esc(s.found ? s.orderNumber : 'SIN PEDIDO'));
html = html.split('{{TIPO}}').join(esc((s.tipoPedido || '').toUpperCase()));
html = html.split('{{FECHA}}').join(esc(s.fecha));
html = html.split('{{HORA}}').join(esc(s.hora));
html = html.split('{{REMITENTE}}').join(esc(s.fromEmail));
html = html.split('{{ASUNTO}}').join(esc(s.subject));
html = html.split('{{CUERPO_TEXTO}}').join(esc(s.bodyText));
html = html.split('{{IMAGENES}}').join(s.imagenesHtml || '<p style="font-size:9pt;color:#000;margin:2mm 0">— Sin planos adjuntos en el correo —</p>');
return [{ json: s, binary: { index_html: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' } } }];

